	}
	sort.Slice(...)
	var b strings.Builder
	for _, op := range sorted {
		fmt.Fprintf(&b, "%d:%d:", int(op.Kind), len(op.CargoID))
		b.WriteString(op.CargoID)
		fmt.Fprintf(&b, ":%d:", len(op.Target))
		b.WriteString(op.Target)
		b.WriteByte(';')
	}
	return b.String()
}
